//! P-IO-5: ephemeral pruning, commit recording, and best-effort reopen.
//!
//! Freezes golden 22 (pruned tree bytes), 23 (pruned three-column reference
//! table), 24 (the eight-column TB commit with the `tb_pruned` record) and 25
//! (best-effort reopen: ephemeral fields reopen to their `Default`, non
//! ephemeral missing fields still reject). Covers the typed `#[tree_space
//! (ephemeral)]` derive round trip, the runtime `DynamicNode.mark_ephemeral`
//! path, the verify pruning-consistency check, the `tb_pruned` column negative
//! checklist, legacy seven-column degradation, and the memory/disk GC domain
//! separation.

use arrow::array::{Array, FixedSizeBinaryArray, Int32Array, ListArray, StringArray};
use arrow::buffer::{OffsetBuffer, ScalarBuffer};
use arrow::datatypes::{DataType, Field, Schema};
use arrow::record_batch::RecordBatch;
use std::sync::Arc;
use tree_space::block::RefId;
use tree_space::ipc::{decode_batch, encode_batch};
use tree_space::layout::tb::{RefRow, prune_image};
use tree_space::tree::codec::{EncodeTree, ImageContent, TreeImage, encode, encode_node, tree_id};
use tree_space::tree::{DynamicField, Slot};
use tree_space::xpath::XPath;
use tree_space::{
    ArrowTable, Blob, Block, BlockKind, Bucket, TreeCodec, TreeNode, TreeNodeMeta, Value,
    canonical_xpath_bytes, encode_ref_table, named_field, positioned_field, ref_table_address,
};

fn hex16(value: &str) -> [u8; 16] {
    let mut bytes = [0; 16];
    for (index, pair) in value.as_bytes().chunks_exact(2).enumerate() {
        bytes[index] = u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap();
    }
    bytes
}

fn unhex(value: &str) -> Vec<u8> {
    (0..value.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&value[index..index + 2], 16).unwrap())
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// The P-IO-5 sample ephemeral tree: a persistent `block` leaf, a persistent
/// node `common/table`, an ephemeral node `scratch/lazy` and an ephemeral chunk
/// group `cache` (two Table chunks).
fn sample_fields() -> Vec<tree_space::ImageField> {
    vec![
        named_field("block", ImageContent::Ref(RefId::from_bytes([0x11; 16]))),
        named_field(
            "common",
            ImageContent::Node(vec![named_field(
                "table",
                ImageContent::Ref(RefId::from_bytes([0x22; 16])),
            )]),
        ),
        named_field(
            "scratch",
            ImageContent::Node(vec![named_field(
                "lazy",
                ImageContent::Ref(RefId::from_bytes([0x33; 16])),
            )]),
        ),
        named_field(
            "cache",
            ImageContent::ChunkGroup {
                kind: BlockKind::Table,
                children: vec![
                    positioned_field(ImageContent::ChunkEntry(RefId::from_bytes([0x44; 16]))),
                    positioned_field(ImageContent::ChunkEntry(RefId::from_bytes([0x55; 16]))),
                ],
            },
        ),
    ]
}

fn sample_prefixes() -> Vec<Vec<u8>> {
    vec![
        canonical_xpath_bytes(&XPath::root().field("scratch")),
        canonical_xpath_bytes(&XPath::root().field("cache")),
    ]
}

const G22_TREE_ADDRESS: &str = "25fb5e48798d234969eaa329aca585af";
/// Golden-22 tree identity (PL-2 M2 re-freeze: `semantic_tree` walk of the
/// pruned form).
const G22_TREE_ID: &str = "98719b9c3328d2e1f5caf0535706b5a5";
const G22_TREE_HEX: &str = "";
const G22_RECORDED_CACHE: &str = "4605000000000000006361636865";
const G22_RECORDED_SCRATCH: &str = "46070000000000000073637261746368";
const G23_REF_ADDRESS: &str = "3aa14961d6d1c041ec82e40cfe25e1f0";
const G23_REF_HEX: &str = "";
const G24_COMMIT_ID: &str = "ea454fc52da0fdc1bcce099eb7f75c9e";
const G24_COMMIT_HEX: &str = "";
/// The canonical bytes of `/scratch` (used to check the pruned ref table).
const PREFIX_SCRATCH: &str = "46070000000000000073637261746368";

#[test]
fn p_io_5_pruned_tree_bytes_and_address_are_frozen() {
    // Golden 22: pruning the sample ephemeral tree under `/scratch` + `/cache`
    // yields the canonical bytes of the persistent form (`block`, `common/
    // table`), whose blob address and tree id are frozen; the recorded maximal
    // pruned prefixes are canonically sorted.
    let (kept, recorded) = prune_image(sample_fields(), &sample_prefixes());
    assert_eq!(
        recorded,
        vec![unhex(G22_RECORDED_CACHE), unhex(G22_RECORDED_SCRATCH)]
    );
    let names = kept
        .iter()
        .map(|field| match &field.locator {
            tree_space::Locator::Named(name) => name.as_str(),
            _ => unreachable!(),
        })
        .collect::<Vec<_>>();
    assert_eq!(names, vec!["block", "common"]);

    let tree_bytes = encode(&TreeImage::new(kept)).unwrap();
    assert_eq!(unhex(G22_TREE_HEX), tree_bytes);
    assert_eq!(
        tree_space::layout::tb::tree_blob_address(&tree_bytes),
        tree_space::ids::Digest::from_bytes(hex16(G22_TREE_ADDRESS))
    );
    assert_eq!(tree_id(&tree_bytes).as_bytes(), hex16(G22_TREE_ID));
    assert_ne!(
        hex16(G22_TREE_ADDRESS),
        hex16(G22_TREE_ID),
        "tree-blob addressing must stay independent of the TreeId"
    );
}

#[test]
fn p_io_5_pruned_ref_table_bytes_frozen_excludes_pruned() {
    // Golden 23: the three-column reference table of the pruned form carries
    // only `/block` and `/common/table`; the pruned `/scratch/lazy` and the
    // `/cache` chunks never appear.
    let rows = vec![
        RefRow {
            xpath: canonical_xpath_bytes(&XPath::root().field("block")),
            ref_id: [0x11; 16],
            address: [0xaa; 16],
        },
        RefRow {
            xpath: canonical_xpath_bytes(&XPath::root().field("common").field("table")),
            ref_id: [0x22; 16],
            address: [0xbb; 16],
        },
    ];
    let bytes = encode_ref_table(&rows).unwrap();
    assert_eq!(unhex(G23_REF_HEX), bytes);
    assert_eq!(
        ref_table_address(&bytes),
        tree_space::ids::Digest::from_bytes(hex16(G23_REF_ADDRESS))
    );
    for row in &rows {
        assert!(
            !row.xpath.starts_with(&unhex(PREFIX_SCRATCH)),
            "the pruned subtree must not appear in the reference table"
        );
    }
}

#[test]
fn p_io_5_pruned_commit_with_tb_pruned_column_is_frozen() {
    // Golden 24: a nine-column TB commit whose `tb_pruned` records the two
    // maximal pruned prefixes and whose `tb_versions` is null. The commit id
    // must equal the P-IO-3 seven-column golden id — the `tb_pruned` column is
    // a derived redundancy excluded from the five-part domain formula (01
    // §1.9.8 (b)5), and the PL-1 S5 ninth `tb_versions` column is excluded the
    // same way (01 §3-1).
    let parent = [0x0a; 16];
    let root = [0x1a; 16];
    let tree_blob = [0x2a; 16];
    let refs = [0x3a; 16];
    let recorded = vec![unhex(G22_RECORDED_CACHE), unhex(G22_RECORDED_SCRATCH)];
    let batch = tree_space::layout::tb::tb_commit_batch(
        9,
        parent,
        root,
        tree_blob,
        refs,
        Some(&recorded),
        None,
    )
    .unwrap();
    let bytes = encode_batch(&batch).unwrap();
    assert_eq!(unhex(G24_COMMIT_HEX), bytes);
    assert_eq!(
        tree_space::layout::tb::tb_commit_id(9, parent, root, tree_blob, refs),
        tree_space::ids::Digest::from_bytes(hex16(G24_COMMIT_ID))
    );
    assert_eq!(
        G24_COMMIT_ID, "ea454fc52da0fdc1bcce099eb7f75c9e",
        "the P-IO-3 golden-19 id must be unchanged by the tb_pruned column"
    );
}

#[test]
fn p_io_5_pruned_image_leaf_set_has_no_pruned_leaves() {
    // The pruned-form leaf walk recomputes only the persistent leaves; the
    // scratch subtree and the cache chunks disappear.
    let (kept, _) = prune_image(sample_fields(), &sample_prefixes());
    let image = TreeImage::new(kept);
    let refs = tree_space::layout::tb::image_leaf_refs(&image).unwrap();
    let paths = refs
        .iter()
        .map(|(xpath, _)| xpath.to_string())
        .collect::<Vec<_>>();
    assert_eq!(paths, vec!["/block", "/common/table"]);
    assert_eq!(
        refs.iter().map(|(_, id)| *id).collect::<Vec<_>>(),
        vec![RefId::from_bytes([0x11; 16]), RefId::from_bytes([0x22; 16]),]
    );
}

// -----------------------------------------------------------------------------
// Typed derive + best-effort reopen (golden 25 + end-to-end)
// -----------------------------------------------------------------------------

#[derive(TreeCodec, TreeNode, Clone, Debug, Default)]
struct Scratch {
    note: Option<Value>,
    tbl: ArrowTable,
}

#[derive(TreeCodec, TreeNode, Clone, Debug)]
struct EphemeralExperiment {
    name: Value,
    data: ArrowTable,
    #[tree_space(ephemeral)]
    scratch: Vec<ArrowTable>,
    #[tree_space(ephemeral)]
    temp: Scratch,
    #[tree_space(ephemeral)]
    extras: Option<Scratch>,
}

fn table(ids: &[i32]) -> ArrowTable {
    let schema = Arc::new(Schema::new(vec![Field::new(
        "value",
        DataType::Int32,
        false,
    )]));
    ArrowTable::try_new(
        RecordBatch::try_new(schema, vec![Arc::new(Int32Array::from(ids.to_vec()))]).unwrap(),
    )
    .unwrap()
}

fn ephemeral_fixture() -> (Bucket, EphemeralExperiment) {
    let data = table(&[1]);
    let chunk_a = table(&[2]);
    let chunk_b = table(&[3]);
    let temp_tbl = table(&[4]);
    let opt_tbl = table(&[5]);
    let mut bucket = Bucket::new();
    for block in [&data, &chunk_a, &chunk_b, &temp_tbl, &opt_tbl] {
        bucket.put(block);
    }
    (
        bucket,
        EphemeralExperiment {
            name: Value::Utf8("exp".into()),
            data,
            scratch: vec![chunk_a, chunk_b],
            temp: Scratch {
                note: Some(Value::Utf8("temp".into())),
                tbl: temp_tbl,
            },
            extras: Some(Scratch {
                note: Some(Value::Utf8("opt".into())),
                tbl: opt_tbl,
            }),
        },
    )
}

#[test]
fn p_io_5_template_ephemeral_prefixes_are_exposed() {
    let mut prefixes = <EphemeralExperiment as TreeNodeMeta>::ephemeral_prefixes();
    prefixes.sort_by_key(|path| path.to_string());
    let mut expected = vec![
        XPath::root().field("scratch"),
        XPath::root().field("temp"),
        XPath::root().field("extras"),
    ];
    expected.sort_by_key(|path| path.to_string());
    assert_eq!(prefixes, expected);
}

#[test]
fn p_io_5_reopen_best_effort_defaults_and_non_ephemeral_still_required() {
    // Golden 25 (behavior): commit a typed tree with pruned ephemeral fields,
    // reopen, and project — ephemeral fields come back as `Default::default()`
    // while persistent fields materialize through the bucket. A missing non
    // ephemeral field still rejects with SchemaMismatch.
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let (bucket, fixture) = ephemeral_fixture();
    let fields = EncodeTree::tree_children(&fixture).unwrap();
    let prefixes = <EphemeralExperiment as TreeNodeMeta>::ephemeral_prefixes()
        .iter()
        .map(canonical_xpath_bytes)
        .collect::<Vec<_>>();
    let receipt = library.commit_pruned(&fields, &prefixes, &bucket).unwrap();
    assert!(receipt.sequence >= 1);

    // The head commit records `tb_pruned` non-null with the three prefixes
    // (nine columns: the P-IO-5 eighth `tb_pruned` plus the PL-1 S5 ninth
    // `tb_versions` side-table pointer).
    let head_batch = decode_batch(&std::fs::read(head_commit_path(temp.path())).unwrap()).unwrap();
    assert_eq!(head_batch.num_columns(), 9);
    let tb_pruned = head_batch
        .column(7)
        .as_any()
        .downcast_ref::<ListArray>()
        .unwrap();
    assert!(
        !tb_pruned.is_null(0),
        "pruned commit records a non-null list"
    );
    let elements = tb_pruned.value(0);
    let binaries = elements
        .as_any()
        .downcast_ref::<arrow::array::BinaryArray>()
        .unwrap();
    assert_eq!(binaries.len(), 3);

    let reopened = tree_space::TbLibrary::open(temp.path().join("library")).unwrap();
    assert_eq!(reopened.verify().unwrap(), 1, "only `data` survives");

    let projected: EphemeralExperiment = reopened.project().unwrap();
    assert_eq!(projected.name, fixture.name);
    assert_eq!(projected.data.ref_id(), fixture.data.ref_id());
    assert!(
        projected.scratch.is_empty(),
        "ephemeral chunk container reopens empty"
    );
    assert_eq!(projected.temp.note, None);
    assert_eq!(
        projected.temp.tbl.ref_id(),
        ArrowTable::default().ref_id(),
        "ephemeral node reopens to its Default"
    );
    assert!(projected.extras.is_none());

    // Non-ephemeral missing fields still reject: a type whose required block
    // field is absent from the supplied image gets SchemaMismatch.
    #[derive(TreeCodec, TreeNode, Clone, Debug)]
    struct NeedsData {
        data: ArrowTable,
    }
    let trimmed = TreeImage::new(vec![named_field(
        "name",
        ImageContent::Inline(fixture.name.clone()),
    )]);
    let error = tree_space::project::<NeedsData>(&trimmed, &bucket).unwrap_err();
    assert_eq!(error.code, tree_space::ErrorCode::SchemaMismatch);
}

#[test]
fn p_io_5_ephemeral_typed_commit_verify_clean_and_reopen_roundtrip() {
    // End-to-end: a full commit reopens with the ephemeral fields materialized;
    // the pruned commit of the same instance verifies clean and reopens the
    // persistent fields with the ephemeral fields at their defaults.
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let (bucket, fixture) = ephemeral_fixture();
    let fields = EncodeTree::tree_children(&fixture).unwrap();
    let prefixes = <EphemeralExperiment as TreeNodeMeta>::ephemeral_prefixes()
        .iter()
        .map(canonical_xpath_bytes)
        .collect::<Vec<_>>();

    // 1. Full-tree commit: everything is written, ephemeral fields materialize.
    let full_bytes = encode_node(&fixture).unwrap();
    let full_refs = fixture.leaf_refs();
    library.commit(&full_bytes, &full_refs, &bucket).unwrap();
    let reopened = tree_space::TbLibrary::open(temp.path().join("library")).unwrap();
    assert_eq!(
        encode_node(&reopened.project::<EphemeralExperiment>().unwrap()).unwrap(),
        full_bytes,
        "a full commit reopens with ephemeral data present (byte-identical)"
    );

    // 2. Pruned commit of the same instance: verifies clean, persistent fields
    // reopen, ephemeral fields return to defaults.
    let receipt = library.commit_pruned(&fields, &prefixes, &bucket).unwrap();
    assert_eq!(receipt.sequence, 2);
    let reopened = tree_space::TbLibrary::open(temp.path().join("library")).unwrap();
    assert_eq!(reopened.verify().unwrap(), 1);
    let projected: EphemeralExperiment = reopened.project().unwrap();
    assert_eq!(projected.name, fixture.name);
    assert_eq!(projected.data.ref_id(), fixture.data.ref_id());
    assert!(projected.scratch.is_empty());
    assert_eq!(projected.temp.note, None);
    assert_eq!(
        projected.temp.tbl.ref_id(),
        ArrowTable::default().ref_id(),
        "ephemeral node reopens to its Default"
    );
    assert!(projected.extras.is_none());

    // The in-memory instance still owns every leaf reference (five block
    // leaves across persistent and ephemeral subtrees).
    assert_eq!(
        fixture.leaf_refs().len(),
        5,
        "data, 2 chunks, temp.tbl, extras.tbl"
    );
}

#[test]
fn p_io_5_dynamic_mark_ephemeral_commits_pruned_ref_table() {
    // DynamicNode::Persistence.mark_ephemeral drives the runtime prefix set:
    // the committed reference table must not contain the pruned subtree, and
    // the reopened image keeps the persistent fields only (best effort).
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let keep_block = Blob::new(vec![9]);
    let scratch_block = Blob::new(vec![8]);
    let keep_id = keep_block.ref_id();
    let scratch_id = scratch_block.ref_id();
    let mut bucket = Bucket::new();
    bucket.put(&keep_block);
    bucket.put(&scratch_block);

    let mut node = tree_space::DynamicNode::new();
    node.insert("keep", DynamicField::Slot(Slot::Ref(keep_id)));
    let mut scratch = tree_space::DynamicNode::new();
    scratch.insert("hidden", DynamicField::Slot(Slot::Ref(scratch_id)));
    node.insert("scratch", DynamicField::Node(scratch));
    node.mark_ephemeral(XPath::root().field("scratch"));

    let image = tree_space::to_image(&node).unwrap();
    let fields = image.children().to_vec();
    let prefixes = node
        .persistence()
        .ephemeral_prefixes()
        .iter()
        .map(canonical_xpath_bytes)
        .collect::<Vec<_>>();
    let receipt = library.commit_pruned(&fields, &prefixes, &bucket).unwrap();
    assert!(receipt.sequence >= 1);

    // The commit-form reference table only references `/keep`.
    let head_id = head_commit_id(temp.path());
    let head = decode_batch(
        &std::fs::read(
            temp.path()
                .join("library")
                .join("commits")
                .join(format!("{}.ipc", hex(&head_id))),
        )
        .unwrap(),
    )
    .unwrap();
    let refs_addr = head
        .column(6)
        .as_any()
        .downcast_ref::<FixedSizeBinaryArray>()
        .unwrap()
        .value(0)
        .to_vec();
    let rows = tree_space::layout::tb::decode_ref_table(
        &std::fs::read(
            temp.path()
                .join("library")
                .join("tb-refs")
                .join(format!("{}.ipc", hex(&refs_addr))),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(
        rows.iter().map(|row| row.xpath.clone()).collect::<Vec<_>>(),
        vec![canonical_xpath_bytes(&XPath::root().field("keep"))]
    );
    let hidden_prefix = unhex(PREFIX_SCRATCH);
    for row in &rows {
        assert!(
            !row.xpath.starts_with(&hidden_prefix),
            "the pruned subtree block must not be referenced"
        );
    }

    // Best effort reopen: the image keeps `/keep`, `/scratch` is gone.
    let resumed_image = reopened_image(temp.path());
    let resumed = tree_space::from_image(&resumed_image).unwrap();
    assert!(resumed.get_field("keep").is_some());
    assert!(resumed.get_field("scratch").is_none());
    let _ = scratch_id;
}

#[test]
fn p_io_5_verify_rejects_pruned_prefix_ref_conflict() {
    // Negative: verify pruning consistency — a commit whose `tb_pruned` records
    // a prefix under which the reference table still has a row is rejected.
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let keep_id = Blob::new(vec![1]).ref_id();
    let hidden_id = Blob::new(vec![2]).ref_id();
    let mut bucket = Bucket::new();
    bucket.put(&Blob::new(vec![1]));
    bucket.put(&Blob::new(vec![2]));

    // A FULL commit: both leaves and both blocks are present.
    let full = TreeImage::new(vec![
        named_field("scratch", ImageContent::Ref(hidden_id)),
        named_field("keep", ImageContent::Ref(keep_id)),
    ]);
    let full_bytes = encode(&full).unwrap();
    let full_refs = tree_space::layout::tb::image_leaf_refs(&full).unwrap();
    library.commit(&full_bytes, &full_refs, &bucket).unwrap();

    // Rewrite the head commit's `tb_pruned` to claim `/scratch` was pruned,
    // while the tree and reference table still carry `/scratch`. Verify must
    // reject the conflict.
    let head_path = head_commit_path(temp.path());
    let batch = decode_batch(&std::fs::read(&head_path).unwrap()).unwrap();
    let mut columns = batch.columns().to_vec();
    columns[7] = Arc::new(lists_of(&[unhex(PREFIX_SCRATCH)]));
    let tampered = RecordBatch::try_new(batch.schema(), columns).unwrap();
    std::fs::write(&head_path, encode_batch(&tampered).unwrap()).unwrap();

    let reopened = tree_space::TbLibrary::open(temp.path().join("library")).unwrap();
    let error = match reopened.verify() {
        Ok(_) => panic!("pruned prefix / reference-table conflict must be rejected"),
        Err(error) => error,
    };
    assert_eq!(error.code, tree_space::ErrorCode::DigestMismatch);
}

#[test]
fn p_io_5_open_rejects_wrong_tb_pruned_column_type() {
    // Negative: an eight-column commit whose `tb_pruned` is not `List<Binary>`
    // must be rejected on open.
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let mut bucket = Bucket::new();
    bucket.put(&Blob::new(vec![3]));
    let image = TreeImage::new(vec![named_field(
        "x",
        ImageContent::Ref(Blob::new(vec![3]).ref_id()),
    )]);
    let tb = encode(&image).unwrap();
    let leaf = tree_space::layout::tb::image_leaf_refs(&image).unwrap();
    library.commit(&tb, &leaf, &bucket).unwrap();

    let head_path = head_commit_path(temp.path());
    let batch = decode_batch(&std::fs::read(&head_path).unwrap()).unwrap();
    let fields = batch
        .schema()
        .fields()
        .iter()
        .enumerate()
        .map(|(index, field)| {
            Arc::new(field.as_ref().clone().with_data_type(if index == 7 {
                DataType::Utf8
            } else {
                field.data_type().clone()
            })) as Arc<arrow::datatypes::Field>
        })
        .collect::<Vec<_>>();
    let mut columns = batch.columns().to_vec();
    columns[7] = Arc::new(StringArray::from(vec!["not a list".to_owned()]));
    let wrong = RecordBatch::try_new(Arc::new(Schema::new(fields)), columns).unwrap();
    std::fs::write(&head_path, encode_batch(&wrong).unwrap()).unwrap();

    let error = match tree_space::TbLibrary::open(temp.path().join("library")) {
        Ok(_) => panic!("wrong tb_pruned column type must be rejected"),
        Err(error) => error,
    };
    assert_eq!(error.code, tree_space::ErrorCode::SchemaMismatch);
}

#[test]
fn p_io_5_legacy_seven_column_commit_degrades_readable() {
    // Legacy: an old seven-column TB commit is readable by the new read end,
    // with `tb_pruned` treated as null (no-pruning semantics).
    //
    // PL-1 S6 semantics update: a seven-column commit carries no `tb_versions`
    // pointer, so no leaf has a version side-table row — every row falls back
    // to payload-magic probing (02 §5.6 step 4, replacing the pre-S6 scan
    // rule "native bytes stay on the IPC/native path"). The blob envelope is
    // itself a canonical IPC frame, so its embedded payload probes `ARROW1`
    // and the leaf restores **healthy** through the IPC plugin — the tree
    // reopens (tree parseable), verify counts the row, and typed projection
    // keeps materializing. A degrade only happens when a side-table literal
    // or the probed magic does not route (the S6 fixtures cover that).
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let mut bucket = Bucket::new();
    bucket.put(&Blob::new(vec![7]));
    let image = TreeImage::new(vec![named_field(
        "blob",
        ImageContent::Ref(Blob::new(vec![7]).ref_id()),
    )]);
    let tb = encode(&image).unwrap();
    let leaf = tree_space::layout::tb::image_leaf_refs(&image).unwrap();
    library.commit(&tb, &leaf, &bucket).unwrap();

    // Downgrade the head commit object to seven columns in place (the commit
    // id is unaffected — `tb_pruned` never enters the five-part domain).
    let head_path = head_commit_path(temp.path());
    let batch = decode_batch(&std::fs::read(&head_path).unwrap()).unwrap();
    let fields7 = batch
        .schema()
        .fields()
        .iter()
        .take(7)
        .map(|field| Arc::new(field.as_ref().clone()))
        .collect::<Vec<_>>();
    let columns7 = batch.columns()[..7].to_vec();
    let seven = RecordBatch::try_new(Arc::new(Schema::new(fields7)), columns7).unwrap();
    let pointers = tree_space::layout::tb::decode_tb_commit_pointers(&seven)
        .unwrap()
        .expect("a seven-column commit still yields TB pointers");
    assert!(
        pointers.pruned.is_none(),
        "legacy commits carry no pruning record"
    );
    assert!(
        pointers.versions.is_none(),
        "legacy commits carry no version side-table pointer"
    );
    std::fs::write(&head_path, encode_batch(&seven).unwrap()).unwrap();

    let reopened = tree_space::TbLibrary::open(temp.path().join("library")).unwrap();
    assert_eq!(reopened.verify().unwrap(), 1);
    assert_eq!(reopened.tree_image().unwrap(), &image);
    let resumed = tree_space::from_image(reopened.tree_image().unwrap()).unwrap();
    assert!(resumed.get_field("blob").is_some());

    // S6 anchor (empirical): the no-side-table blob leaf falls back to
    // payload-magic probing (02 §5.6 step 4) — the envelope frame's embedded
    // IPC payload starts with `ARROW1`, so the leaf restores HEALTHY through
    // the IPC plugin. The probe fallback is the semantic replacement of the
    // pre-S6 "native bytes stay on the IPC/native path" scan rule; a degrade
    // only happens for a side-table label that does not route (S6 fixtures).
    let blob_id = Blob::new(vec![7]).ref_id();
    assert_eq!(
        reopened.bucket().unwrap().degraded().len(),
        0,
        "the probed IPC envelope restores healthy, not degraded"
    );
    let envelope = reopened
        .bucket()
        .unwrap()
        .get(blob_id)
        .expect("the magic-probed blob leaf is a healthy envelope");
    assert_eq!(envelope.kind, BlockKind::Blob);

    // Typed projection materializes the healthy leaf through the bullet-proof
    // read path (the projection that the legacy commit must keep working).
    #[derive(tree_space::TreeCodec, tree_space::TreeNode, Clone, Debug)]
    struct BlobSurface {
        blob: Blob,
    }
    let projected = reopened.project::<BlobSurface>().unwrap();
    assert_eq!(projected.blob.bytes(), &[7]);
}

#[test]
fn p_io_5_gc_memory_vs_disk_domain_for_ephemeral() {
    // GC double-domain (archive §3.5 MUST): the memory-domain GC roots include
    // the live instance's ephemeral-subtree leaf refs, while the disk-domain
    // GC reclaims a pruned block once it is no longer referenced (a full commit
    // first wrote it, the pruned commit drops it, the windowed sweep reclaims
    // the blob).
    let temp = tempfile::tempdir().unwrap();
    let library = tree_space::TbLibrary::create(temp.path().join("library")).unwrap();
    let keep_block = Blob::new(vec![0xaa]);
    let scratch_block = Blob::new(vec![0xbb]);
    let keep_id = keep_block.ref_id();
    let scratch_id = scratch_block.ref_id();
    let mut bucket = Bucket::new();
    bucket.put(&keep_block);
    bucket.put(&scratch_block);

    let mut node = tree_space::DynamicNode::new();
    node.insert("keep", DynamicField::Slot(Slot::Ref(keep_id)));
    let mut scratch = tree_space::DynamicNode::new();
    scratch.insert("hidden", DynamicField::Slot(Slot::Ref(scratch_id)));
    node.insert("scratch", DynamicField::Node(scratch));

    // Full commit: both blobs are written to `tb-blocks/`.
    let image = tree_space::to_image(&node).unwrap();
    let full_bytes = encode(&image).unwrap();
    let full_refs = node.leaf_refs();
    let first = library.commit(&full_bytes, &full_refs, &bucket).unwrap();

    // Pruned commit: `/scratch` is no longer referenced; its blob is not
    // rewritten.
    node.mark_ephemeral(XPath::root().field("scratch"));
    let fields = image.children().to_vec();
    let prefixes = node
        .persistence()
        .ephemeral_prefixes()
        .iter()
        .map(canonical_xpath_bytes)
        .collect::<Vec<_>>();
    let second = library.commit_pruned(&fields, &prefixes, &bucket).unwrap();
    assert_eq!(second.sequence, first.sequence + 1);

    // Memory domain: the live instance roots still include the ephemeral leaf.
    let root_ids = tree_space::memory_gc_roots([&node as &dyn TreeNode]);
    assert!(root_ids.contains(&keep_id));
    assert!(
        root_ids.contains(&scratch_id),
        "in-memory GC roots keep the ephemeral leaf"
    );

    let root = temp.path().join("library");
    let keep_addr = tree_space::layout::tb::block_blob_address(&keep_block.envelope().encode());
    let scratch_addr =
        tree_space::layout::tb::block_blob_address(&scratch_block.envelope().encode());
    assert!(
        root.join("tb-blocks")
            .join(format!("{keep_addr}.bin"))
            .exists()
    );
    assert!(
        root.join("tb-blocks")
            .join(format!("{scratch_addr}.bin"))
            .exists()
    );

    // Disk domain: windowed GC reaches only the pruned head; the pruned block
    // is swept while the persistent block survives.
    let report = library.gc(second.sequence).unwrap();
    assert!(report.reclaimed >= 1);
    assert!(
        root.join("tb-blocks")
            .join(format!("{keep_addr}.bin"))
            .exists()
    );
    assert!(
        !root
            .join("tb-blocks")
            .join(format!("{scratch_addr}.bin"))
            .exists(),
        "the pruned block must be reclaimed by the disk-domain GC"
    );
}

// -----------------------------------------------------------------------------
// Test helpers
// -----------------------------------------------------------------------------

/// Returns the path of the head commit object.
fn head_commit_path(root: &std::path::Path) -> std::path::PathBuf {
    root.join("library")
        .join("commits")
        .join(format!("{}.ipc", hex(&head_commit_id(root))))
}

/// Returns the raw id bytes of the head commit.
fn head_commit_id(root: &std::path::Path) -> Vec<u8> {
    let committed =
        decode_batch(&std::fs::read(root.join("library").join("committed")).unwrap()).unwrap();
    committed
        .column(0)
        .as_any()
        .downcast_ref::<FixedSizeBinaryArray>()
        .unwrap()
        .value(0)
        .to_vec()
}

/// Returns the restored tree image of an opened library (used for the dynamic
/// best-effort assertions).
fn reopened_image(_root: &std::path::Path) -> tree_space::TreeImage {
    // The reopened image is obtained by decoding the committed tree bytes.
    // `p_io_5_dynamic_mark_ephemeral_commits_pruned_ref_table` reopens the
    // library itself; this helper decodes the commit's tree blob so the
    // assertion can run on a fresh open handle.
    let opened = tree_space::TbLibrary::open(_root.join("library")).unwrap();
    opened.tree_image().unwrap().clone()
}

/// Builds a `List<Binary>` array over one list row carrying `prefixes`.
fn lists_of(prefixes: &[Vec<u8>]) -> ListArray {
    let field = Arc::new(Field::new_list_field(DataType::Binary, true));
    let child =
        arrow::array::BinaryArray::from_iter(prefixes.iter().map(|prefix| Some(prefix.as_slice())));
    let offsets = OffsetBuffer::new(ScalarBuffer::from(vec![0_i32, prefixes.len() as i32]));
    ListArray::new(field, offsets, Arc::new(child), None)
}
